/*
 * A118296  Start with 21 and repeatedly reverse the digits and add 1 to get
 *          the next term.
 * https://oeis.org/A118296
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn, easy
 * Formula:   a(1) = 21, a(n) = rev_decimal(a(n-1)) + 1 for n > 1
 * Range:     u8 n <= 94, u16 n <= 94, u32 n <= 94, u64 n <= 94, u128 n <= 94,
 *            big any n
 * Helpers:   rev_decimal, seq_realloc
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by repeatedly reversing the decimal digits of the
   previous term and adding one.  This implementation uses a simple cache
   so that values are computed only once, in O(n) time per call. */

#include <stddef.h>                     /* for size_t */
#include <stdlib.h>                     /* for seq_realloc */
#include "../utils/rev_decimal.h"       /* rev_decimal() */
#include "../utils/seq_realloc.h"       /* seq_realloc() */

seq_t a(idx_t n)
{
    /* static cache: cache[i] holds a(i) for i >= 1 */
    static seq_t *cache = NULL;   /* pointer to allocated array */
    static size_t cap = 0;        /* allocated size (including dummy slot 0) */
    static idx_t  len = 0;        /* highest index that is currently cached */

    if (n < 1)
        return (seq_t)0;          /* undefined below offset, but safe */

    /* Allocate or grow cache if needed */
    if ((size_t)n + 1 > cap) {
        size_t newcap = (size_t)n + 1;
        seq_t *tmp = seq_realloc(cache, cap, newcap);
        cache = tmp;
        cap = newcap;
    }

    /* Compute terms up to n */
    if (len == 0) {
        /* initialise the first term */
        cache[1] = (seq_t)21;
        len = 1;
    }

    for (idx_t i = len + 1; i <= n; ++i) {
        cache[i] = rev_decimal(cache[i-1]) + (seq_t)1;
    }
    len = n;

    return cache[n];
}
